import React, { useState } from "react";
import logo from "../../../assets/images/Logo.png";
import { AiOutlineBars } from "react-icons/ai";

import "../Navbar/Navbar.css";
function Navbar() {
  const [showNavbar, setShowNavbar] = useState(false);

  /* nav scrool*/
  function scrollToTestDiv(des) {
    const divElement = document.getElementById(des);
    divElement.scrollIntoView({ behavior: "smooth", block: "start" });
  }

  return (
    <section className="navbar">
      <div className="max-width">
        <div className="nav">
          <div className="logo">
            <img src={logo} alt="" />
          </div>
          <div className="liste">
            <ul className={showNavbar ? "menu active" : "menu"}>
              <li
                onClick={() => {
                  scrollToTestDiv("home");
                }}
              >
                Home{" "}
              </li>
              <li
                onClick={() => {
                  scrollToTestDiv("wrapper");
                }}
              >
                Health benefits
              </li>
              <li
                onClick={() => {
                  scrollToTestDiv("about");
                }}
              >
                About
              </li>
            </ul>
          </div>
          <div className="icon">
            <AiOutlineBars
              className="menu-icon"
              onClick={() => {
                setShowNavbar(!showNavbar);
              }}
            />
          </div>
        </div>
      </div>
    </section>
  );
}

export default Navbar;
