import React, { useEffect, useState } from "react";
import "../Details_products/Details_products.css";
import { Link, useParams } from "react-router-dom";
import img from "../assets/images/salad-1.png";
import Loader from "../Loading/Loader";
import axios from "axios";
import { XRapidAPIHost, XRapidAPIKey } from "../constants";
function Details_products() {
  const { id } = useParams();
  const [item, setItem] = useState("");
  useEffect(() => {
    const headers = {
      "X-RapidAPI-Key": XRapidAPIKey,
      "X-RapidAPI-Host": XRapidAPIHost,
    };

    axios
      .get("https://tasty.p.rapidapi.com/recipes/get-more-info", {
        params: {
          id: id,
        },
        headers: headers,
      })
      .then((response) => {
        console.log(response.data);
        setItem(response.data);
      })
      .catch((error) => {
        console.log(error);
      });
  }, []);
  return item.nutrition !== undefined ? (
    <section className="details-products">
      <div className="max-width">
        <div className="container-products">
          <div className="left">
            <div className="img">
              <img src={item.thumbnail_url} alt="" />
            </div>
          </div>
          <div className="right">
            <div className="title">{item.name}</div>
            <div className="description">{item.description}</div>
            <div className="carbo">
              Nutrition :
              <div className="items">
                <div className="item carbohydrates">
                  <span>Calories</span> {item.nutrition.calories}
                </div>
                <div className="line"></div>
                <div className="item fat">
                  {" "}
                  <span>Fat</span> {item.nutrition.fat}
                </div>
                <div className="line"></div>
                <div className="item protein">
                  {" "}
                  <span>Protein</span> {item.nutrition.protein}
                </div>
                <div className="line"></div>
                <div className="item fiber">
                  {" "}
                  <span>Sugar</span> {item.nutrition.sugar}
                </div>
                <div className="line"></div>
                <div className="item fiber">
                  {" "}
                  <span>Fiber</span> {item.nutrition.fiber}
                </div>
              </div>
              <div className="ingredient">
                {item.instructions.map((instruction) => {
                  return <div className="instruction">
                    <div>{instruction.position}</div>
                    <div>{instruction.display_text}</div>
                  </div>;
                })}
              </div>
              
                <a href={item.original_video_url} target="_blank">
                <button >  Watch Videos </button>

                </a>

                
            </div>
          </div>
        </div>
      </div>
    </section>
  ) : (
    <div className="container-loader">
      <Loader />
    </div>
    
  );
}

export default Details_products;
