import React, { useEffect, useState } from "react";
import "../Wrapper/Wrapper.css";
import axios from "axios";
import { XRapidAPIHost, XRapidAPIKey } from "../../../constants";
import { Link } from "react-router-dom";
// import Swiper core and required modules
import { Swiper, SwiperSlide } from "swiper/react";

// Import Swiper styles
import "swiper/css";
import "swiper/css/pagination";
import { Pagination, Autoplay } from "swiper";

function Wrapper() {
  const [receipt, setReceipt] = useState();
  const slides = Array.from({ length: 1000 }).map(
    (el, index) => `Slide ${index + 1}`
  );

  useEffect(() => {
    const headers = {
      "X-RapidAPI-Key": XRapidAPIKey,
      "X-RapidAPI-Host": XRapidAPIHost,
    };

    axios
      .get("https://tasty.p.rapidapi.com/recipes/list", {
        params: {
          from: "0",
          size: "25",
          tags: "under_30_minutes",
        },
        headers: headers,
      })
      .then((response) => {
        console.log(response.data["results"]);
        setReceipt(response.data["results"]);
      })
      .catch((error) => {
        console.log(error);
      });
  }, []);

  return (
    <section className="wrapper" id="wrapper">
      <div className="max-width">
        <div className="title">Our special dish</div>
        <div className="cards">
          <Swiper
            autoplay={{ delay: 2500, disableOnInteraction: false }}
            modules={[Pagination, Autoplay]}
            className="mySwiper"
            spaceBetween={40}
            slidesPerView={3}
            onSlideChange={() => console.log("slide change")}
            onSwiper={(swiper) => console.log(swiper)}
            breakpoints={{
              0: {
                slidesPerView: 1,
              },
              750: {
                slidesPerView: 2,
              },
              900: {
                slidesPerView: 3,
              }
              
            }}
          >
            {receipt && receipt.length > 0
              ? receipt.map((item) => {
                  return (
                    <SwiperSlide>
                      <Link to={`/detailProduit/${item["id"]}`}>
                        <div className="card">
                          <img src={item["thumbnail_url"]} alt="" />
                          <div className="titre"> {item["name"]} </div>
                          <div className="text"> {item["description"]} </div>
                        </div>
                      </Link>
                    </SwiperSlide>
                  );
                })
              : ""}
          </Swiper>
        </div>
      </div>
    </section>
  );
}

export default Wrapper;
