import "./App.css";
import Acceuil from "./Acceuil/Acceuil";
import Details_products from "./Details_products/Details_products";
import { BrowserRouter as Router, Switch, Route } from "react-router-dom";
import Navbar from "./Acceuil/components/Navbar/Navbar";
function App() {
  return (
    <Router>
      <div className="App">
         <Navbar /> 
        <Switch>
          <Route exact path="/" component={Acceuil} />
          <Route exact path="/detailProduit/:id" component={Details_products} />
        </Switch>
      </div>
    </Router>
  );
}

export default App;
