import React from "react";
import "./About.css";
import about from "../../../assets/images/about.jpg";
function About() {
  return (
    <section className="about" id="about">
      <div className="max-width">
        <div className="content">
          <div className="left">
            <div className="title">Care about nutrition for your health</div>
            <div className="text">
            That's a great summary of key points for a healthy diet. It's important to keep in mind that everyone's nutritional needs are unique, and a balanced diet that works for one person may not work for another. Consulting a registered dietitian or healthcare provider can help you determine the best dietary approach for you based on your individual needs and goals.
            </div>
            <button>Learn More </button>
          </div>
          <div className="right">
            <img src={about} alt="" />
          </div>
        </div>
      </div>
    </section>
  );
}

export default About;
